#!/usr/bin/env node
/*
 * Concatenates the classic shell scripts listed in js/bootstrap/load-order.json
 * into js/avian-game.bundle.js. Pure Node stdlib — no dependencies.
 *
 * Side-effects:
 *   - Embeds a content-hash header in the bundle and exposes it as
 *     `globalThis.__AVIAN_BUNDLE_HASH__` for runtime debugging.
 *   - Rewrites sw.js' CACHE_VERSION to `avian-ascent-<hash>` so service-worker
 *     cache invalidates whenever the game scripts or cached shell UI change.
 *
 * Usage:
 *   node scripts/build-bundle.js          # one-shot build
 *   node scripts/build-bundle.js --watch  # rebuild on source change
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT = path.resolve(__dirname, '..');
const MANIFEST = path.join(ROOT, 'js', 'bootstrap', 'load-order.json');
const OUTPUT = path.join(ROOT, 'js', 'avian-game.bundle.js');
const SW = path.join(ROOT, 'sw.js');
const HASH_FILE = path.join(ROOT, 'js', 'avian-game.bundle.hash');
const CACHED_SHELL_FILES = [
  'index.html',
  'css/main.css',
  'css/sprites.css',
  'css/shop.css',
  'css/ui.css',
  'site.webmanifest',
];

function readManifest() {
  const raw = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
  const list = raw.gameShellScripts || raw;
  if (!Array.isArray(list)) {
    throw new Error('load-order.json: gameShellScripts must be an array');
  }
  return list;
}

function rewriteSwCacheVersion(hash) {
  let sw;
  try {
    sw = fs.readFileSync(SW, 'utf8');
  } catch (_e) {
    return; // sw.js missing — skip silently
  }
  const next = sw.replace(
    /const CACHE_VERSION = '[^']+';/,
    `const CACHE_VERSION = 'avian-ascent-${hash}';`,
  );
  if (next !== sw) fs.writeFileSync(SW, next, 'utf8');
}

function buildOnce() {
  const start = Date.now();
  const files = readManifest();

  let body = '';
  let totalBytes = 0;
  for (const rel of files) {
    const full = path.join(ROOT, rel);
    if (!fs.existsSync(full)) {
      throw new Error(`Missing manifest entry: ${rel}`);
    }
    const src = fs.readFileSync(full, 'utf8');
    totalBytes += src.length;
    body += `\n;/* === ${rel.replace(/\\/g, '/')} === */\n`;
    body += src;
  }

  const hasher = crypto.createHash('sha256').update(body);
  for (const rel of CACHED_SHELL_FILES) {
    hasher.update(`\n/* cached shell: ${rel} */\n`);
    hasher.update(fs.readFileSync(path.join(ROOT, rel)));
  }
  const hash = hasher.digest('hex').slice(0, 12);
  const header =
    '/* Avian Ascent — generated by scripts/build-bundle.js. Do not edit by hand.\n' +
    ` * Source order: js/bootstrap/load-order.json\n` +
    ` * Bundle hash:  ${hash}\n` +
    ' */\n' +
    `globalThis.__AVIAN_BUNDLE_HASH__ = ${JSON.stringify(hash)};\n`;

  fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
  fs.writeFileSync(OUTPUT, header + body, 'utf8');
  fs.writeFileSync(HASH_FILE, hash + '\n', 'utf8');

  rewriteSwCacheVersion(hash);

  const ms = Date.now() - start;
  console.log(
    `[bundle] wrote js/avian-game.bundle.js (${files.length} files, ${(totalBytes / 1024).toFixed(1)} KiB source, hash ${hash}) in ${ms} ms`,
  );
  return files;
}

function watch() {
  let pending = false;
  let timer = null;
  let watchedFiles = [];
  const watchers = [];

  function rebuild() {
    if (pending) return;
    pending = true;
    clearTimeout(timer);
    timer = setTimeout(() => {
      pending = false;
      try {
        const next = buildOnce();
        const nextSet = new Set(next.map((p) => p.replace(/\\/g, '/')));
        const prevSet = new Set(watchedFiles);
        const changed =
          next.length !== watchedFiles.length ||
          [...nextSet].some((f) => !prevSet.has(f));
        if (changed) attachWatchers(next);
      } catch (err) {
        console.error('[bundle] build failed:', err.message);
      }
    }, 80);
  }

  function attachWatchers(files) {
    while (watchers.length) {
      try {
        watchers.pop().close();
      } catch {
        /* noop */
      }
    }
    watchedFiles = files.map((p) => p.replace(/\\/g, '/'));
    for (const rel of [...files, ...CACHED_SHELL_FILES]) {
      const full = path.join(ROOT, rel);
      try {
        const w = fs.watch(full, { persistent: true }, () => rebuild());
        watchers.push(w);
      } catch (err) {
        console.warn(`[bundle] cannot watch ${rel}: ${err.message}`);
      }
    }
    try {
      const w = fs.watch(MANIFEST, { persistent: true }, () => rebuild());
      watchers.push(w);
    } catch (err) {
      console.warn(`[bundle] cannot watch load-order.json: ${err.message}`);
    }
  }

  const initial = buildOnce();
  attachWatchers(initial);
  console.log(`[bundle] watching ${initial.length} files for changes…`);
}

const args = process.argv.slice(2);
if (args.includes('--watch') || args.includes('-w')) {
  watch();
} else {
  buildOnce();
}
